UPDATE ai_config SET protocol = #{protocol}, endpoint = #{endpoint}, model = #{model}, auth_scheme = #{authScheme},
api_key_cipher = #{apiKeyCipher}, api_key_key_id = #{apiKeyKeyId},
max_output_tokens = #{maxOutputTokens}, output_limit_field = #{outputLimitField}, timeout_seconds = #{timeoutSeconds}, enabled = #{enabled}, connection_revision = #{connectionRevision}, tested_revision = #{testedRevision}, tested_at = #{testedAt}, tested_by = #{testedBy}, operator_account_id = #{operatorAccountId}, version = version + 1 WHERE org_id = #{orgId} AND version = #{version}

UPDATE ai_config
SET tested_revision = #{revision},
    tested_at = CURRENT_TIMESTAMP(6),
    tested_by = #{testedBy}
WHERE org_id = #{orgId}
  AND connection_revision = #{revision}

UPDATE ai_config
SET enabled = #{enabled},
    operator_account_id = #{operatorAccountId},
    version = version + 1
WHERE org_id = #{orgId}
  AND version = #{expectedVersion}
